mapper.update:
UPDATE book_reservation
SET status = 4
WHERE book_id = #{bookId}
  AND status = 3
  AND notify_time IS NOT NULL
  AND notify_time < #{cutoff}

mapper.insert:
INSERT INTO book_reservation (user_id, book_id, reserve_time, status, notify_time)
SELECT #{userId}, #{bookId}, #{reserveTime}, #{status}, #{notifyTime}
WHERE NOT EXISTS (
    SELECT 1
    FROM book_reservation
    WHERE user_id = #{userId}
      AND book_id = #{bookId}
      AND status IN (0, 3)
)

mapper.select:
SELECT br.*, u.user_name, b.name AS book_name FROM book_reservation br LEFT JOIN user u ON br.user_id = u.id LEFT JOIN book b ON br.book_id = b.id
ORDER BY br.id DESC
LIMIT #{size} OFFSET #{current}

