UPDATE book_reservation
SET status = 2
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 0

UPDATE book_reservation
SET status = 3,
    notify_time = #{notifyTime}
WHERE id = #{id}
  AND status = 0
